import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Loader } from 'lucide-react'; // Tailwind spinner icon

export const ProtectedRoute = ({ children, allowedRoles }) => {
  const { user, isLoading } = useAuth();
  const location = useLocation();

  // 1. Show a loading spinner while checking the HTTP-only cookie
  if (isLoading) {
    return (
      <div className="flex h-screen w-full items-center justify-center bg-gray-50">
        <Loader className="animate-spin text-farmGreen" size={48} />
      </div>
    );
  }

  // 2. If no user is found, redirect to login, saving their intended destination
  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // 3. (Optional) If route requires specific roles (e.g., 'admin' or 'farmer')
  if (allowedRoles && !allowedRoles.includes(user.role)) {
    // Redirect to a generic safe page or an "Unauthorized" page
    return <Navigate to="/" replace />;
  }

  // 4. If all checks pass, render the requested page
  return children;
};
